css:
& { padding:0; gap:0; overflow:hidden; isolation:isolate; }
.st-photo { position:absolute; inset:0; width:100%; height:100%; object-fit:cover; z-index:-3; }
.st-shade { position:absolute; inset:0; z-index:-2; background:linear-gradient(90deg,var(--bg),color-mix(in srgb,var(--bg) 90%,transparent) 28%,color-mix(in srgb,var(--bg) 20%,transparent) 74%),linear-gradient(0deg,color-mix(in srgb,var(--bg) 95%,transparent),transparent 70%); }
.st-head { position:absolute; left:100px; top:82px; width:1350px; }
.st-kicker { font:500 22px/1.3 var(--font-mono,var(--mono)); letter-spacing:.13em; text-transform:uppercase; color:var(--accent); }
.st-head h2 { font-family:var(--font-display,var(--font)); font-size:76px; line-height:1.06; max-width:27ch; margin:22px 0 0; text-wrap:balance; }
.st-head p:empty,.st-head h2:empty { display:none; }
.st-intro { font-size:28px; color:var(--muted); line-height:1.4; max-width:53ch; margin-top:24px!important; }
.st-items { list-style:none; padding:0; margin:0; }
.st-items li { opacity:1!important; transform:none!important; }
.st-items li b { display:block; font-weight:650; line-height:1.14; text-wrap:balance; overflow-wrap:anywhere; }
.st-items li span { display:block; line-height:1.4; overflow-wrap:anywhere; }
.st-endnote { position:absolute; left:100px; right:100px; bottom:95px; font-size:32px; line-height:1.3; color:var(--ink); opacity:0; transition:opacity .65s; max-width:58ch; }
&:has([data-template-end].in) .st-endnote,&:has([data-template-end]:not([data-step])) .st-endnote { opacity:1; }
[data-template-end] { position:absolute; width:0; height:0; overflow:hidden; }
&[data-body-motion="none"] * { transition:none!important; }
@media (prefers-reduced-motion:reduce) { & * { transition:none!important; animation:none!important; } }
.st-shade { background:linear-gradient(0deg,var(--bg) 2%,color-mix(in srgb,var(--bg) 35%,transparent) 68%),linear-gradient(90deg,color-mix(in srgb,var(--bg) 93%,transparent),transparent 90%); }
.om-rail { position:absolute; left:170px; right:170px; top:692px; height:2px; background:var(--accent); opacity:0; transform:scaleX(.05); transform-origin:left; transition:opacity .7s,transform 1.1s cubic-bezier(.2,.8,.2,1); }
.om-items { position:absolute; inset:0; counter-reset:observation; }
.om-items li { position:absolute; width:355px; padding:24px 28px; border-left:3px solid var(--accent); background:color-mix(in srgb,var(--bg) 88%,transparent); color:var(--ink); counter-increment:observation; transition:left 1.1s cubic-bezier(.2,.8,.2,1),top 1.1s cubic-bezier(.2,.8,.2,1),width 1.1s,background .6s,border-color .6s; }
.om-items li::before { content:counter(observation,decimal-leading-zero); display:block; font:22px/1.2 var(--font-mono,var(--mono)); color:var(--accent); margin-bottom:16px; }
.om-items li b { font-size:29px; }.om-items li span { max-height:0; opacity:0; font-size:40px; font-family:var(--font-display,var(--font)); font-weight:650; color:var(--accent); transition:max-height .7s,opacity .7s,margin .7s; }
.om-items li:nth-child(1) { left:150px; top:420px; }.om-items li:nth-child(2) { left:760px; top:540px; }.om-items li:nth-child(3) { left:1330px; top:380px; }.om-items li:nth-child(4) { left:730px; top:785px; }
.om-items li.in,.om-items li:not([data-step]) { top:580px; border-color:var(--line); background:color-mix(in srgb,var(--bg) 95%,transparent); }
.om-items li.in span,.om-items li:not([data-step]) span { max-height:150px; opacity:1; margin-top:22px; }
.om-items li.step-current { border-color:var(--accent); }.om-items li.step-past b { color:var(--muted); }
&:has(.om-items li.in) .om-rail { opacity:1; transform:scaleX(1); }
&:has(.om-items li:nth-child(2):last-child) .om-items li:nth-child(1):is(.in,:not([data-step])) { left:100.0px; width:680px; }
&:has(.om-items li:nth-child(2):last-child) .om-items li:nth-child(2):is(.in,:not([data-step])) { left:1140.0px; width:680px; }
&:has(.om-items li:nth-child(3):last-child) .om-items li:nth-child(1):is(.in,:not([data-step])) { left:100.0px; width:460px; }
&:has(.om-items li:nth-child(3):last-child) .om-items li:nth-child(2):is(.in,:not([data-step])) { left:730.0px; width:460px; }
&:has(.om-items li:nth-child(3):last-child) .om-items li:nth-child(3):is(.in,:not([data-step])) { left:1360.0px; width:460px; }
&:has(.om-items li:nth-child(4):last-child) .om-items li:nth-child(1):is(.in,:not([data-step])) { left:100.0px; width:345px; }
&:has(.om-items li:nth-child(4):last-child) .om-items li:nth-child(2):is(.in,:not([data-step])) { left:558.3px; width:345px; }
&:has(.om-items li:nth-child(4):last-child) .om-items li:nth-child(3):is(.in,:not([data-step])) { left:1016.7px; width:345px; }
&:has(.om-items li:nth-child(4):last-child) .om-items li:nth-child(4):is(.in,:not([data-step])) { left:1475.0px; width:345px; }
&:has([data-template-end].in), &:has([data-template-end]:not([data-step])) { .om-rail { opacity:1; transform:scaleX(1); } .om-items li { top:580px; } .om-items li b { color:var(--muted); } .om-items li span { max-height:150px; opacity:1; margin-top:22px; } }
